package com.school.management.config;
import com.school.management.entity.*; import com.school.management.repository.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; import org.springframework.security.crypto.password.PasswordEncoder; import java.math.BigDecimal; import java.time.LocalDate; import java.util.*;
@Configuration public class DataInitializer {
 @Bean CommandLineRunner seed(AppUserRepository users,SchoolClassRepository classes,StudentRepository students,AttendanceRepository attendance,PasswordEncoder encoder,@Value("${app.seed.admin-email}") String email,@Value("${app.seed.admin-password}") String password){return args->{if(users.count()==0){AppUser u=new AppUser();u.setEmail(email.toLowerCase(Locale.ROOT));u.setFullName("School Administrator");u.setRole("ADMIN");u.setPasswordHash(encoder.encode(password));users.save(u);}if(classes.count()==0){String[][] rows={{"M1","Mr. Vanna Sok","Room 101","Mon-Fri 7:00-11:30","General Studies"},{"M2","Ms. Sreymom Tan","Room 102","Mon-Fri 7:00-11:30","General Studies"},{"M3","Mr. Piseth Chan","Room 201","Mon-Fri 7:00-11:30","Science Track"},{"M4","Ms. Kolab Pich","Room 202","Mon-Fri 7:00-11:30","Social Track"},{"M5","Mr. Sovann Im","Room 301","Mon-Fri 7:00-11:30","Science Track"},{"M6","Ms. Ratana Khem","Room 302","Mon-Fri 7:00-11:30","Social Track"}};int i=1;for(String[] row:rows){SchoolClass c=new SchoolClass();c.setClassCode(String.format("CLS-%03d",i++));c.setName(row[0]);c.setTeacher(row[1]);c.setRoom(row[2]);c.setSchedule(row[3]);c.setSubject(row[4]);classes.save(c);}}if(students.count()==0){String[][] rows={{"Sokha Chann","Male","2002-03-14","012-345-678","sokha.chann@school.edu","Phnom Penh, Cambodia","M1","Active","3.8"},{"Sreyleak Pov","Female","2003-07-22","095-234-567","sreyleak.pov@school.edu","Siem Reap, Cambodia","M2","Active","3.5"},{"Dara Meas","Male","2001-11-05","077-456-789","dara.meas@school.edu","Battambang, Cambodia","M3","Active","2.9"},{"Pisey Keo","Female","2002-01-18","070-567-890","pisey.keo@school.edu","Phnom Penh, Cambodia","M4","Inactive","3.2"},{"Bunna Lim","Male","2000-05-30","096-678-901","bunna.lim@school.edu","Kampot, Cambodia","M5","Active","3.9"},{"Channary Uth","Female","2000-09-12","088-789-012","channary.uth@school.edu","Phnom Penh, Cambodia","M6","Active","3.6"}};int i=1;for(String[] row:rows){Student s=new Student();s.setStudentCode(String.format("STU-%03d",i++));s.setName(row[0]);s.setGender(row[1]);s.setDob(LocalDate.parse(row[2]));s.setPhone(row[3]);s.setEmail(row[4]);s.setAddress(row[5]);s.setClassName(row[6]);s.setTeacher("");s.setStatus(row[7]);s.setGpa(new BigDecimal(row[8]));s.setAvatar(Arrays.stream(row[0].split(" ")).map(x->x.substring(0,1)).reduce("",String::concat));s.setEnrolled(LocalDate.now());students.save(s);}}};}
}
